ALTER TABLE public.provider_facility_agreement_versions ADD COLUMN scope_fingerprint text, ADD COLUMN creator_person_mfn_id text;
CREATE FUNCTION public.request_facility_quote(_draft uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_drafts;provider uuid;cid uuid;eid uuid;BEGIN SELECT * INTO d FROM public.trip_drafts WHERE id=_draft AND user_id=auth.uid() AND submitted_trip_id IS NULL FOR UPDATE;provider:=nullif(d.payload->>'selectedProviderWorkspaceId','')::uuid;IF d.id IS NULL OR NOT public.can_manage_account_connections(d.workspace_id) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=d.workspace_id AND account_type IN ('facility','hospital') AND status='active' AND NOT is_test_account) THEN RAISE EXCEPTION 'Facility quote unavailable';END IF;SELECT id INTO cid FROM public.account_business_connections WHERE active AND ((workspace_a=d.workspace_id AND workspace_b=provider) OR (workspace_b=d.workspace_id AND workspace_a=provider));IF cid IS NULL OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=provider AND account_type='provider' AND status='active' AND NOT is_test_account) THEN RAISE EXCEPTION 'Accepted provider required';END IF;INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT provider,'facility_quote_requested',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('draftId',d.id,'facilityId',d.workspace_id,'providerId',provider,'connectionId',cid,'scope',public.customer_quote_fingerprint(d.payload),'service',coalesce(d.payload->>'transportType','ambulatory'),'date',d.payload->>'pickupDate','time',d.payload->>'pickupTime','roundTrip',d.payload->>'tripType'='round_trip') FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=d.workspace_id RETURNING id INTO eid;RETURN eid;END $$;
REVOKE ALL ON FUNCTION public.request_facility_quote(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.request_facility_quote(uuid) TO authenticated;
CREATE FUNCTION public.propose_facility_quote(_request uuid,_cents integer,_policy text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.account_relationship_events;eid uuid;BEGIN SELECT * INTO e FROM public.account_relationship_events WHERE id=_request AND action='facility_quote_requested';IF e.id IS NULL OR NOT public.can_manage_provider_customer_pricing(e.workspace_id) OR _cents<0 OR length(trim(_policy))<3 OR length(_policy)>3000 OR NOT EXISTS(SELECT 1 FROM public.account_business_connections WHERE id=(e.details->>'connectionId')::uuid AND active) THEN RAISE EXCEPTION 'Quote unavailable';END IF;INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT (e.details->>'facilityId')::uuid,'facility_quote_proposed',auth.uid(),p.mfn_id,w.mfn_id,e.details||jsonb_build_object('requestId',e.id,'totalCents',_cents,'policy',_policy,'providerActor',auth.uid()) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=e.workspace_id RETURNING id INTO eid;RETURN eid;END $$;
REVOKE ALL ON FUNCTION public.propose_facility_quote(uuid,integer,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.propose_facility_quote(uuid,integer,text) TO authenticated;
CREATE FUNCTION public.accept_facility_quote(_proposal uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.account_relationship_events;d public.trip_drafts;aid uuid;v integer;BEGIN SELECT * INTO e FROM public.account_relationship_events WHERE id=_proposal AND action='facility_quote_proposed';IF e.id IS NULL OR NOT public.can_manage_account_connections(e.workspace_id) THEN RAISE EXCEPTION 'Quote unavailable';END IF;PERFORM 1 FROM public.account_business_connections WHERE id=(e.details->>'connectionId')::uuid AND active FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Connection unavailable';END IF;IF NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.workspace_id=(e.details->>'providerId')::uuid AND m.user_id=(e.details->>'providerActor')::uuid AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND w.status='active' AND NOT w.is_test_account) THEN RAISE EXCEPTION 'Provider confirmation unavailable';END IF;SELECT * INTO d FROM public.trip_drafts WHERE id=(e.details->>'draftId')::uuid AND user_id=auth.uid() AND workspace_id=e.workspace_id AND submitted_trip_id IS NULL FOR UPDATE;IF d.id IS NULL OR public.customer_quote_fingerprint(d.payload) IS DISTINCT FROM e.details->>'scope' OR d.payload->>'pickupDate' IS DISTINCT FROM e.details->>'date' OR d.payload->>'pickupTime' IS DISTINCT FROM e.details->>'time' OR d.payload->>'transportType' IS DISTINCT FROM e.details->>'service' THEN RAISE EXCEPTION 'Trip changed; new quote required';END IF;IF EXISTS(SELECT 1 FROM public.account_relationship_events WHERE action='facility_quote_accepted' AND details->>'proposalId'=_proposal::text) THEN SELECT (details->>'agreementId')::uuid INTO aid FROM public.account_relationship_events WHERE action='facility_quote_accepted' AND details->>'proposalId'=_proposal::text;RETURN aid;END IF;SELECT coalesce(max(version),0)+1 INTO v FROM public.provider_facility_agreement_versions WHERE connection_id=(e.details->>'connectionId')::uuid;INSERT INTO public.provider_facility_agreement_versions(connection_id,provider_workspace_id,facility_workspace_id,version,quote_reference,approved_total_cents,bill_to_workspace_id,responsible_payer_workspace_id,provider_policy_snapshot,provider_confirmed_by,facility_confirmed_by,scope_fingerprint,creator_person_mfn_id) VALUES((e.details->>'connectionId')::uuid,(e.details->>'providerId')::uuid,e.workspace_id,v,_proposal::text,(e.details->>'totalCents')::integer,e.workspace_id,e.workspace_id,e.details->>'policy',(e.details->>'providerActor')::uuid,auth.uid(),e.details->>'scope',(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid())) RETURNING id INTO aid;UPDATE public.trip_drafts SET customer_quote_history=customer_quote_history||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'version',jsonb_array_length(customer_quote_history)+1,'facilityAgreementId',aid,'agreementVersion',v,'providerWorkspaceId',e.details->>'providerId','totalCents',(e.details->>'totalCents')::integer,'lines',jsonb_build_array(jsonb_build_object('label','Approved facility trip quote','cents',(e.details->>'totalCents')::integer)),'terms',e.details->>'policy','formFingerprint',e.details->>'scope','trip',jsonb_build_object('service',CASE WHEN e.details->>'service'='gurney' THEN 'stretcher' ELSE e.details->>'service' END,'pickupDate',e.details->>'date','pickupTime',e.details->>'time','roundTrip',e.details->'roundTrip'))) WHERE id=d.id;INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,details) VALUES(e.workspace_id,'facility_quote_accepted',auth.uid(),jsonb_build_object('proposalId',_proposal,'agreementId',aid,'draftId',d.id,'version',v));RETURN aid;END $$;
REVOKE ALL ON FUNCTION public.accept_facility_quote(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.accept_facility_quote(uuid) TO authenticated;
COMMENT ON COLUMN public.provider_facility_agreement_versions.scope_fingerprint IS 'Exact trip-specific bilateral quote scope; no private rate access or collection.';